#!/usr/bin/env node
/**
 * Ally guide wire-contract generator and validator.
 *
 * The contract lives in ONE file — src/guide/contract/guide-contract.schema.json
 * — and is consumed by three apps in two languages. This script turns it into:
 *
 *   ally-be  src/guide/contract/generated/guide-contract.ts
 *   ally-web apps/ally-helpline-dashboard/src/types/generated/guide-contract.ts
 *   ally-ai-learn app/core/guide/contract.py   (pydantic v2)
 *
 *   node scripts/guide-contract/codegen.mjs           write the generated files
 *   node scripts/guide-contract/codegen.mjs --check   exit 1 if any is stale
 *   node scripts/guide-contract/codegen.mjs --validate-fixtures
 *                                                      check every fixture in
 *                                                      src/guide/contract/fixtures
 *
 * Deliberately dependency-free: it understands only the small JSON Schema
 * subset the contract is allowed to use (see the schema's `description`), and
 * fails loudly on anything else rather than generating something subtly wrong.
 */
import { readFileSync, writeFileSync, mkdirSync, readdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const BE_ROOT = resolve(HERE, '..', '..');
const MONOREPO_ROOT = resolve(BE_ROOT, '..');

export const SCHEMA_PATH = join(
  BE_ROOT,
  'src/guide/contract/guide-contract.schema.json',
);
export const FIXTURES_DIR = join(BE_ROOT, 'src/guide/contract/fixtures');

export const OUTPUTS = {
  beTs: join(BE_ROOT, 'src/guide/contract/generated/guide-contract.ts'),
  webTs: join(
    MONOREPO_ROOT,
    'ally-web/apps/ally-helpline-dashboard/src/types/generated/guide-contract.ts',
  ),
  aiLearnPy: join(MONOREPO_ROOT, 'ally-ai-learn/app/core/guide/contract.py'),
};

const HEADER_NOTE =
  'GENERATED by ally-be/scripts/guide-contract/codegen.mjs from ' +
  'ally-be/src/guide/contract/guide-contract.schema.json. Do not edit by hand: ' +
  'change the schema and re-run the script.';

export function loadSchema(path = SCHEMA_PATH) {
  return JSON.parse(readFileSync(path, 'utf8'));
}

// ---------------------------------------------------------------------------
// Schema helpers
// ---------------------------------------------------------------------------

const refName = (ref) => {
  const match = /^#\/\$defs\/(.+)$/.exec(ref);
  if (!match) throw new Error(`Unsupported $ref "${ref}" — only #/$defs/X`);
  return match[1];
};

const typesOf = (node) =>
  Array.isArray(node.type) ? node.type : node.type ? [node.type] : [];

const isStringEnumDef = (def) =>
  typesOf(def).includes('string') && Array.isArray(def.enum) && !def.properties;

const isUnionDef = (def) => Array.isArray(def.oneOf);

const isObjectDef = (def) =>
  typesOf(def).includes('object') && !isUnionDef(def);

/** Own + inherited (x-extends) properties and required keys. */
export function flattenObject(defs, def) {
  let properties = {};
  let required = [];
  if (def['x-extends']) {
    const base = flattenObject(defs, defs[refName(def['x-extends'])]);
    properties = { ...base.properties };
    required = [...base.required];
  }
  properties = { ...properties, ...(def.properties ?? {}) };
  required = [...new Set([...required, ...(def.required ?? [])])];
  const additionalProperties =
    def.additionalProperties ??
    (def['x-extends']
      ? flattenObject(defs, defs[refName(def['x-extends'])])
          .additionalProperties
      : undefined);
  return { properties, required, additionalProperties };
}

/** Discriminator value (`type` const) of an object def in a oneOf. */
const discriminatorOf = (defs, ref) => {
  const def = defs[refName(ref)];
  const { properties } = flattenObject(defs, def);
  const value = properties.type?.const;
  if (typeof value !== 'string') {
    throw new Error(
      `oneOf member ${refName(ref)} needs a string \`type\` const to discriminate on`,
    );
  }
  return value;
};

const ALLOWED_KEYS = new Set([
  '$schema',
  '$id',
  '$defs',
  '$ref',
  'title',
  'description',
  'type',
  'enum',
  'const',
  'properties',
  'required',
  'additionalProperties',
  'items',
  'oneOf',
  'maxLength',
  'x-extends',
  'x-contract-version',
]);

/** Refuse anything outside the supported subset, with the path to it. */
export function assertSupportedSubset(node, path = '#') {
  if (node === null || typeof node !== 'object' || Array.isArray(node)) return;
  for (const key of Object.keys(node)) {
    if (path.endsWith('/properties') || path.endsWith('/$defs')) {
      assertSupportedSubset(node[key], `${path}/${key}`);
      continue;
    }
    if (!ALLOWED_KEYS.has(key)) {
      throw new Error(`Unsupported schema keyword "${key}" at ${path}`);
    }
    const value = node[key];
    if (key === 'properties' || key === '$defs') {
      assertSupportedSubset(value, `${path}/${key}`);
    } else if (key === 'items' || key === 'additionalProperties') {
      assertSupportedSubset(value, `${path}/${key}`);
    } else if (key === 'oneOf') {
      value.forEach((member, i) =>
        assertSupportedSubset(member, `${path}/oneOf/${i}`),
      );
    }
  }
}

// ---------------------------------------------------------------------------
// TypeScript
// ---------------------------------------------------------------------------

const upperSnake = (name) =>
  name
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2')
    .toUpperCase();

const tsLiteral = (value) =>
  value === null
    ? 'null'
    : typeof value === 'string'
      ? `'${value}'`
      : String(value);

const tsDoc = (text, indent = '') =>
  text ? `${indent}/** ${text.replace(/\*\//g, '*\\/')} */\n` : '';

function tsType(node, indent) {
  if (node.$ref) return refName(node.$ref);
  if (node.const !== undefined) return tsLiteral(node.const);
  if (Array.isArray(node.enum)) return node.enum.map(tsLiteral).join(' | ');
  const types = typesOf(node);
  const parts = types.map((t) => {
    switch (t) {
      case 'string':
        return 'string';
      case 'integer':
      case 'number':
        return 'number';
      case 'boolean':
        return 'boolean';
      case 'null':
        return 'null';
      case 'array':
        return `Array<${tsType(node.items ?? {}, indent)}>`;
      case 'object':
        return tsInlineObject(node, indent);
      default:
        throw new Error(`Unsupported type "${t}"`);
    }
  });
  return parts.length ? parts.join(' | ') : 'unknown';
}

function tsInlineObject(node, indent) {
  const props = node.properties ?? {};
  const keys = Object.keys(props);
  if (!keys.length) return 'Record<string, unknown>';
  const required = new Set(node.required ?? []);
  const inner = indent + '  ';
  const lines = keys.map(
    (key) =>
      `${tsDoc(props[key].description, inner)}${inner}${key}${required.has(key) ? '' : '?'}: ${tsType(props[key], inner)};`,
  );
  return `{\n${lines.join('\n')}\n${indent}}`;
}

/**
 * `eslintDisable`: ally-be lints with the prettier rule, which the generator's
 * own layout would trip; ally-web's lint passes as-is and reports an unused
 * directive, so only the ally-be copy carries one. Both repos keep the
 * generated file out of `prettier --check` via .prettierignore.
 */
export function generateTypeScript(schema, { eslintDisable = false } = {}) {
  const defs = schema.$defs;
  const out = [
    ...(eslintDisable ? ['/* eslint-disable */'] : []),
    `// ${HEADER_NOTE}`,
    '',
    `export const GUIDE_CONTRACT_VERSION = ${schema['x-contract-version']} as const;`,
    '',
  ];
  for (const [name, def] of Object.entries(defs)) {
    if (isStringEnumDef(def)) {
      const values = def.enum.map(tsLiteral);
      out.push(
        tsDoc(def.description) + `export type ${name} = ${values.join(' | ')};`,
      );
      out.push(
        `export const ${upperSnake(name)}_VALUES = [${values.join(', ')}] as const;`,
        '',
      );
    } else if (isUnionDef(def)) {
      const members = def.oneOf.map((m) => refName(m.$ref));
      out.push(
        tsDoc(def.description) +
          `export type ${name} =\n  | ${members.join('\n  | ')};`,
      );
      out.push(
        `export const ${upperSnake(name)}_TYPES = [${def.oneOf
          .map((m) => tsLiteral(discriminatorOf(defs, m.$ref)))
          .join(', ')}] as const;`,
        '',
      );
    } else if (isObjectDef(def)) {
      const ext = def['x-extends']
        ? ` extends ${refName(def['x-extends'])}`
        : '';
      const body = tsInlineObject(
        { ...def, properties: def.properties ?? {} },
        '',
      );
      out.push(
        tsDoc(def.description) +
          `export interface ${name}${ext} ${body === 'Record<string, unknown>' ? '{}' : body}`,
        '',
      );
    } else {
      throw new Error(`$defs/${name}: not an enum, object or oneOf union`);
    }
  }
  return (
    out
      .join('\n')
      .replace(/\n{3,}/g, '\n\n')
      .trimEnd() + '\n'
  );
}

// ---------------------------------------------------------------------------
// Python (pydantic v2)
// ---------------------------------------------------------------------------

const snake = (name) =>
  name
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2')
    .toLowerCase();

const pyLiteral = (value) =>
  value === null
    ? 'None'
    : typeof value === 'string'
      ? `"${value}"`
      : String(value);

const PY_RESERVED = new Set(['type', 'id', 'format', 'hash', 'input', 'from']);

function pyType(node, nested) {
  if (node.$ref) return refName(node.$ref);
  if (node.const !== undefined) return `Literal[${pyLiteral(node.const)}]`;
  if (Array.isArray(node.enum)) {
    const nonNull = node.enum.filter((v) => v !== null);
    const lit = `Literal[${nonNull.map(pyLiteral).join(', ')}]`;
    return node.enum.includes(null) ? `Optional[${lit}]` : lit;
  }
  const types = typesOf(node).filter((t) => t !== 'null');
  const nullable = typesOf(node).includes('null');
  const mapped = types.map((t) => {
    switch (t) {
      case 'string':
        return 'str';
      case 'integer':
        return 'int';
      case 'number':
        return 'float';
      case 'boolean':
        return 'bool';
      case 'array':
        return `list[${pyType(node.items ?? {}, nested)}]`;
      case 'object':
        if (node.properties && Object.keys(node.properties).length) {
          return nested();
        }
        return 'dict[str, Any]';
      default:
        throw new Error(`Unsupported type "${t}"`);
    }
  });
  const inner =
    mapped.length > 1 ? `Union[${mapped.join(', ')}]` : (mapped[0] ?? 'Any');
  return nullable ? `Optional[${inner}]` : inner;
}

/** Order defs so every class is declared after the classes it references. */
function pyOrder(defs) {
  const deps = (node, acc = new Set()) => {
    if (!node || typeof node !== 'object') return acc;
    if (node.$ref) acc.add(refName(node.$ref));
    if (node['x-extends']) acc.add(refName(node['x-extends']));
    for (const value of Object.values(node)) {
      if (value && typeof value === 'object') deps(value, acc);
    }
    return acc;
  };
  const ordered = [];
  const seen = new Set();
  const visit = (name, stack = new Set()) => {
    if (seen.has(name)) return;
    if (stack.has(name)) throw new Error(`Cyclic $ref through ${name}`);
    stack.add(name);
    for (const dep of deps(defs[name])) if (dep !== name) visit(dep, stack);
    stack.delete(name);
    seen.add(name);
    ordered.push(name);
  };
  Object.keys(defs).forEach((name) => visit(name));
  return ordered;
}

function pyClass(name, node, base, emitted) {
  const lines = [];
  const props = node.properties ?? {};
  const required = new Set(node.required ?? []);
  const nestedClasses = [];
  if (node.description)
    lines.push(`    """${node.description.replace(/"""/g, "'''")}"""`, '');
  for (const [key, prop] of Object.entries(props)) {
    const nestedName = `${name}${key[0].toUpperCase()}${key.slice(1)}`;
    const type = pyType(prop, () => {
      nestedClasses.push(pyClass(nestedName, prop, '_GuideModel', emitted));
      return nestedName;
    });
    const field =
      PY_RESERVED.has(snake(key)) && key !== 'type'
        ? `${snake(key)}_`
        : snake(key);
    const alias = field === key ? '' : `alias="${key}"`;
    const isRequired = required.has(key);
    let rhs;
    if (isRequired) {
      rhs = alias ? ` = Field(${alias})` : '';
    } else {
      rhs = alias ? ` = Field(default=None, ${alias})` : ' = None';
    }
    const annotated =
      isRequired || type.startsWith('Optional[') ? type : `Optional[${type}]`;
    lines.push(`    ${field}: ${annotated}${rhs}`);
  }
  if (!Object.keys(props).length && !node.description) lines.push('    pass');
  return [
    ...nestedClasses,
    `class ${name}(${base}):\n${lines.join('\n')}\n`,
  ].join('\n\n');
}

export function generatePython(schema) {
  const defs = schema.$defs;
  const out = [
    '# flake8: noqa',
    `# ${HEADER_NOTE}`,
    '"""Ally guide wire contract (pydantic v2). See ally-be guide-contract.schema.json."""',
    '',
    'from typing import Annotated, Any, Literal, Optional, Union',
    '',
    'from pydantic import BaseModel, ConfigDict, Field',
    '',
    `GUIDE_CONTRACT_VERSION = ${schema['x-contract-version']}`,
    '',
    '',
    'class _GuideModel(BaseModel):',
    '    # Consumers ignore unknown fields so ally-be can add optional fields',
    '    # without breaking a deployed worker; strictness lives in the contract',
    '    # tests, not at runtime.',
    '    model_config = ConfigDict(populate_by_name=True, extra="ignore")',
    '',
  ];
  for (const name of pyOrder(defs)) {
    const def = defs[name];
    if (isStringEnumDef(def)) {
      out.push('', `${name} = Literal[${def.enum.map(pyLiteral).join(', ')}]`);
    } else if (isUnionDef(def)) {
      const members = def.oneOf.map((m) => refName(m.$ref));
      out.push(
        '',
        `${name} = Annotated[`,
        `    Union[${members.join(', ')}],`,
        '    Field(discriminator="type"),',
        ']',
      );
    } else if (isObjectDef(def)) {
      const base = def['x-extends'] ? refName(def['x-extends']) : '_GuideModel';
      out.push('', '', pyClass(name, def, base));
    }
  }
  return (
    out
      .join('\n')
      .replace(/\n{4,}/g, '\n\n\n')
      .trimEnd() + '\n'
  );
}

// ---------------------------------------------------------------------------
// Validator (contract tests)
// ---------------------------------------------------------------------------

const jsType = (value) =>
  value === null
    ? 'null'
    : Array.isArray(value)
      ? 'array'
      : Number.isInteger(value)
        ? 'integer'
        : typeof value;

export function validate(schema, defName, value) {
  const defs = schema.$defs;
  const errors = [];
  const check = (node, val, path) => {
    if (node.$ref) {
      const def = defs[refName(node.$ref)];
      return isObjectDef(def) && def['x-extends']
        ? check(
            { ...def, ...flattenObject(defs, def), 'x-extends': undefined },
            val,
            path,
          )
        : check(def, val, path);
    }
    if (isUnionDef(node)) {
      const match = node.oneOf.find(
        (member) => discriminatorOf(defs, member.$ref) === val?.type,
      );
      if (!match) {
        errors.push(`${path}: no oneOf member with type "${val?.type}"`);
        return;
      }
      return check(match, val, path);
    }
    if (node.const !== undefined && val !== node.const) {
      errors.push(`${path}: expected const ${JSON.stringify(node.const)}`);
    }
    if (Array.isArray(node.enum) && !node.enum.includes(val)) {
      errors.push(`${path}: ${JSON.stringify(val)} not in enum`);
      return;
    }
    const types = typesOf(node);
    if (types.length) {
      const actual = jsType(val);
      const ok = types.some(
        (t) => t === actual || (t === 'number' && actual === 'integer'),
      );
      if (!ok) {
        errors.push(`${path}: expected ${types.join('|')}, got ${actual}`);
        return;
      }
    }
    if (
      typeof val === 'string' &&
      node.maxLength &&
      val.length > node.maxLength
    ) {
      errors.push(`${path}: longer than ${node.maxLength}`);
    }
    if (Array.isArray(val) && node.items) {
      val.forEach((item, i) => check(node.items, item, `${path}[${i}]`));
    }
    if (jsType(val) === 'object' && (node.properties || node.required)) {
      const flat = node['x-extends'] ? flattenObject(defs, node) : node;
      for (const key of flat.required ?? []) {
        if (!(key in val)) errors.push(`${path}: missing required "${key}"`);
      }
      for (const [key, child] of Object.entries(val)) {
        const prop = flat.properties?.[key];
        if (!prop) {
          if (flat.additionalProperties === false) {
            errors.push(`${path}: unexpected property "${key}"`);
          }
          continue;
        }
        check(prop, child, `${path}.${key}`);
      }
    }
  };
  check({ $ref: `#/$defs/${defName}` }, value, defName);
  return errors;
}

/** Each fixture file: { "def": "<Name>", "valid": [...], "invalid": [...] }. */
export function validateFixtures(schema = loadSchema(), dir = FIXTURES_DIR) {
  const failures = [];
  for (const file of readdirSync(dir).filter((f) => f.endsWith('.json'))) {
    const fixture = JSON.parse(readFileSync(join(dir, file), 'utf8'));
    (fixture.valid ?? []).forEach((value, i) => {
      const errors = validate(schema, fixture.def, value);
      if (errors.length)
        failures.push(`${file} valid[${i}]: ${errors.join('; ')}`);
    });
    (fixture.invalid ?? []).forEach((value, i) => {
      if (!validate(schema, fixture.def, value).length) {
        failures.push(`${file} invalid[${i}] was accepted`);
      }
    });
  }
  return failures;
}

// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

export function renderAll(schema = loadSchema()) {
  assertSupportedSubset(schema);
  return {
    [OUTPUTS.beTs]: generateTypeScript(schema, { eslintDisable: true }),
    [OUTPUTS.webTs]: generateTypeScript(schema),
    [OUTPUTS.aiLearnPy]: generatePython(schema),
  };
}

function main(argv) {
  const schema = loadSchema();
  if (argv.includes('--validate-fixtures')) {
    const failures = validateFixtures(schema);
    if (failures.length) {
      console.error(failures.join('\n'));
      process.exit(1);
    }
    console.log('guide-contract: every fixture matches the schema');
    return;
  }
  const rendered = renderAll(schema);
  if (argv.includes('--check')) {
    const stale = Object.entries(rendered).filter(([path, content]) => {
      try {
        return readFileSync(path, 'utf8') !== content;
      } catch {
        return true;
      }
    });
    if (stale.length) {
      console.error(
        'guide-contract: generated files are stale — run `node scripts/guide-contract/codegen.mjs` in ally-be:\n' +
          stale.map(([path]) => `  ${path}`).join('\n'),
      );
      process.exit(1);
    }
    console.log('guide-contract: generated files are up to date');
    return;
  }
  for (const [path, content] of Object.entries(rendered)) {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
    console.log(`wrote ${path}`);
  }
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(process.argv[1]).href
) {
  main(process.argv.slice(2));
}
